import re
for f in ['xl/worksheets/sheet1.xml','xl/worksheets/sheet2.xml']:
    data=open(f).read()
    print('\n===',f)
    rows=re.findall(r'<row .*?</row>', data)
    for row in rows:
        # just print coordinate + value/f
        cells=re.findall(r'<c r="([A-Z0-9]+)"([^>]*)>(.*?)</c>', row)
        out=[]
        for ref,attrs,inner in cells:
            m=re.search(r'<t>([^<]*)</t>', inner)
            if m:
                out.append(f'{ref}="str:{m.group(1)}"')
            elif '<f>' in inner:
                out.append(f'{ref}="f"')
            else:
                out.append(f'{ref}=empty(style)' if 's=' in attrs else f'{ref}=empty')
        print(' | '.join(out))
